public static int controlFlow(int _limit)
{
    int i;
    int total;
    ;
    for (i = 1; i <= _limit; i++)
    {
        if (i > 5)
        {
            total += i;
        }
        else
        {
            total -= i;
        }
    }

    while (total > 100)
    {
        total = total div 2;
    }

    switch (total)
    {
        case 0:
            total = 1;
            break;

        case 1, 2:
            total = 3;
            break;

        default:
            total = -1;
            break;
    }

    return total;
}

public static void databaseAccess(str _account)
{
    CustTable custTable;
    ;
    while select custTable
        where custTable.AccountNum == _account
    {
        info(custTable.AccountNum);
    }

    select firstonly custTable;

    try
    {
        ttsbegin;
        custTable.insert();
        ttscommit;
    }
    catch (Exception::Error)
    {
        ttsabort;
        error('insert failed');
    }
}
